insert into toolbox_tool_click_events(
    event_id, tool_id, source, user_id, trace_id, counted, clicked_at
)
select #{eventId}, #{toolId}, #{source}, #{userId}, #{traceId}, false, #{clickedAt}
where not exists (
    select 1 from toolbox_tool_click_events where event_id = #{eventId}
)
